function handleLocalStorageError(operation, error) {
    if (error instanceof DOMException) {
        if (!localStorageWarned) {
            Log.Warn("Couldn't access noVNC settings, are cookies disabled?");
            localStorageWarned = true;
        }
        Log.Debug("'" + operation + "' failed: " + error);
    } else {
        throw error;
    }
}

function localStorageSetItem(name, value) {
    try {
        localStorage.setItem(name, value);
    } catch (error) {
        handleLocalStorageError("localStorage.setItem(" + [name, value].join(",") + ")", error);
    }
}

function localStorageGetItem(name) {
    try {
        return localStorage.getItem(name);
    } catch (error) {
        handleLocalStorageError("localStorage.getItem(" + name + ")", error);
        return undefined;
    }
}

function localStorageRemoveItem(name) {
    try {
        localStorage.removeItem(name);
    } catch (error) {
        handleLocalStorageError("localStorage.removeItem(" + name + ")", error);
    }
}

